  "allowed_sources": {
    "IK-188721101:L72:span1": {
      "text": "the said tenant Sh. Ramesh Kumar had parted with possession and sub-let and assigned the same initially to one Sh. Ghanshyam Dass and subsequently to Sh. Bhagwan Dass, who were his father and brother respectively.",
